using DriveOS.Modules.CurriculumPedagogy.Domain.Curricula;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Persistence.Configurations;
internal sealed class CurriculumConfiguration:IEntityTypeConfiguration<Curriculum>{public void Configure(EntityTypeBuilder<Curriculum>b){b.ToTable("curricula");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new CurriculumId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.Code).HasMaxLength(40);b.Property(x=>x.Name).HasMaxLength(160);b.Property(x=>x.Description).HasMaxLength(2000);b.Property(x=>x.CountryCode).HasMaxLength(2);b.Property(x=>x.LicenseCategoryCode).HasMaxLength(30);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.ArchivedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.CreatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LastModifiedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.HasIndex(x=>new{x.OrganizationId,x.Code}).IsUnique();b.HasMany(x=>x.Versions).WithOne().HasForeignKey(x=>x.CurriculumId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Versions).UsePropertyAccessMode(PropertyAccessMode.Field);b.Ignore(x=>x.DomainEvents);b.Ignore(x=>x.LatestVersionNumber);}}
internal sealed class CurriculumVersionConfiguration:IEntityTypeConfiguration<CurriculumVersion>{public void Configure(EntityTypeBuilder<CurriculumVersion>b){b.ToTable("curriculum_versions");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new CurriculumVersionId(x)).ValueGeneratedNever();b.Property(x=>x.CurriculumId).HasConversion(x=>x.Value,x=>new CurriculumId(x));b.Property(x=>x.SourceVersionId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new CurriculumVersionId(x.Value):null);b.Property(x=>x.NameSnapshot).HasMaxLength(160);b.Property(x=>x.DescriptionSnapshot).HasMaxLength(2000);b.Property(x=>x.CountryCodeSnapshot).HasMaxLength(2);b.Property(x=>x.LicenseCategoryCodeSnapshot).HasMaxLength(30);b.Property(x=>x.ChangeSummary).HasMaxLength(1000);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.CreatedByUserId).HasConversion(x=>x.Value,x=>new UserId(x));b.Property(x=>x.PublishedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.HasIndex(x=>new{x.CurriculumId,x.VersionNumber}).IsUnique();b.HasMany(x=>x.Modules).WithOne().HasForeignKey(x=>x.CurriculumVersionId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Modules).UsePropertyAccessMode(PropertyAccessMode.Field);}}
